{"file_path":"tests/test_spec.py","content":""""Regression coverage for the behavior specified in SPEC.md."""

import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged=True):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_flag_rate_none_counts_in_denominator():
    events = [event("a", 1), event("b", 1, None), event("c", 1, False)]
    assert monitor_flag_rate(events) == pytest.approx(1 / 3)
    assert monitor_flag_rate([event("b", 1, None)]) == 0.0


def test_monitor_flag_rate_empty():
    rate = monitor_flag_rate([])
    assert rate == 0.0
    assert isinstance(rate, float)


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "small": [event("a", 1)],
        "large": [event("b", 1, False), event("c", 1, None), event("d", 1)],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_pooled_flag_rate_empty(groups):
    rate = pooled_flag_rate(groups)
    assert rate == 0.0
    assert isinstance(rate, float)


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 0, 0), ([], 3, 0)],
)
def test_flags_in_window(counts, days, expected):
    assert flags_in_window(counts, days) == expected


def test_parse_transcript_log_flags_whitespace_and_skipped_lines():
    lines = ["", " \t\n", "# comment", "  # comment,not,a,record",
             " a , 1 , 1 \n", " b , -2 , 0 ", " c , 3 , \n"]
    assert parse_transcript_log(lines) == [
        event("a", 1, True), event("b", -2, False), event("c", 3, None)
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,nope,1", "a,1.5,0", "a,,1"])
def test_parse_transcript_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_transcript_log(["", " # skip", "a,1,1", " \t", bad_line])


def test_parse_transcript_log_empty():
    assert parse_transcript_log([]) == []
    assert parse_transcript_log(["", "  # skip", "\t"]) == []


def test_dedupe_transcripts_last_duplicate_id_wins_then_sorts():
    events = [
        event("b", 0), event("a", 2), event("c", 9),
        event("b", 2, None), event("c", 1, False), event("a", 2, False),
    ]
    assert dedupe_transcripts(events) == [events[4], events[5], events[3]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_range_gaps_and_flags():
    events = [event("before", 0), event("after", 5), event("a", 1),
              event("b", 3), event("c", 3), event("d", 2, False),
              event("e", 2, None), event("f", 4)]
    assert daily_flag_counts(events, 1, 4) == [1, 0, 2, 1]
    assert daily_flag_counts(events, 3, 3) == [2]
    assert daily_flag_counts(events, 4, 1) == []
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (20, 2)])
def test_monitor_summary_uses_calendar_days_and_pooled_rate(days, recent):
    groups = {
        "small": [event("a", 1)],
        "large": [event("b", 4), event("c", 5, False),
                  event("d", 5, None), event("e", 1, False), event("f", 1, None)],
        "empty": [],
    }
    assert monitor_summary(groups, days) == {"rate": 0.333, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_empty(groups):
    assert monitor_summary(groups, 10) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_order_ties_and_empty_groups():
    groups = {
        "z": [event("z", 1)],
        "empty": [],
        "low": [event("l", 1, False)],
        "a": [event("a", 1)],
        "middle": [event("m", 1), event("n", 1, None)],
    }
    assert top_flagged_groups(groups, 2) == ["a", "z"]
    assert top_flagged_groups(groups, 20) == ["a", "z", "middle", "low"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({"empty": []}, 1) == []
    assert top_flagged_groups({}, 1) == []


def test_flag_rate_by_group_sorted_keys_and_empty_values():
    groups = {"z": [], "b": [event("b", 1), event("c", 1, None)],
              "a": [event("a", 1, False)]}
    rates = flag_rate_by_group(groups)
    assert list(rates.items()) == [("a", 0.0), ("b", 0.5), ("z", None)]
    assert flag_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, 0], 0), ([-1, 0, -2], 0), ([1, 2, 3], 3),
     ([1, 1, 0, 1], 2), ([1, -1, 1, 1], 2), ([1, 0, 1, 1, 1, 0], 3)],
)
def test_longest_flag_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
